-- Migración 0012. REFERENCIAS_TIPOS clasifica la referencia externa de un lote.
-- LOTES_REFERENCIAS une el lote con esa referencia por el ID del tipo.
-- PACKING nace como semilla. No tiene llave foránea hacia otro sistema.
-- No editar este archivo. El siguiente cambio va en una migración nueva
-- y debe reflejarse en db/init.sql.

BEGIN;

CREATE TABLE "REFERENCIAS_TIPOS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now()
);

INSERT INTO "REFERENCIAS_TIPOS" ("ID", "CODIGO", "NOMBRE", "ES_SEMILLA") VALUES
  (1, 'PACKING', 'Packing', true);

SELECT setval(
  pg_get_serial_sequence('"REFERENCIAS_TIPOS"', 'ID'),
  (SELECT MAX("ID") FROM "REFERENCIAS_TIPOS")
);

CREATE TABLE "LOTES_REFERENCIAS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ID_LOTE" integer NOT NULL,
  "ID_TIPO" integer NOT NULL,
  "REFERENCIA" text NOT NULL,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "LOTES_REFERENCIAS_ID_LOTE_FK"
    FOREIGN KEY ("ID_LOTE") REFERENCES "LOTES" ("ID") ON DELETE CASCADE,
  CONSTRAINT "LOTES_REFERENCIAS_ID_TIPO_FK"
    FOREIGN KEY ("ID_TIPO") REFERENCES "REFERENCIAS_TIPOS" ("ID"),
  CONSTRAINT "LOTES_REFERENCIAS_REFERENCIA_CHK" CHECK (
    length(btrim("REFERENCIA")) > 0
  )
);

CREATE INDEX "LOTES_REFERENCIAS_ID_LOTE_IDX"
  ON "LOTES_REFERENCIAS" ("ID_LOTE");

CREATE INDEX "LOTES_REFERENCIAS_ID_TIPO_IDX"
  ON "LOTES_REFERENCIAS" ("ID_TIPO");

CREATE INDEX "LOTES_REFERENCIAS_REFERENCIA_IDX"
  ON "LOTES_REFERENCIAS" ("ID_TIPO", "REFERENCIA");

CREATE TRIGGER "REFERENCIAS_TIPOS_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "REFERENCIAS_TIPOS"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

CREATE TRIGGER "LOTES_REFERENCIAS_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "LOTES_REFERENCIAS"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

ALTER TABLE "REFERENCIAS_TIPOS" OWNER TO packing;
ALTER TABLE "LOTES_REFERENCIAS" OWNER TO packing;

COMMIT;
